            &lt;img src=&quot;$banner-logo-left$&quot; alt=&quot;&quot; class=&quot;banner-logo-left&quot;&gt;
            &lt;div&gt;
                &lt;h1 class=&quot;title&quot;&gt;$title$&lt;/h1&gt;
                &lt;p class=&quot;subtitle&quot;&gt;$subtitle$&lt;/p&gt;
            &lt;/div&gt;
        &lt;/div&gt;
        &lt;!-- Then the rest of the document goes here --&gt;
        $body$
        &lt;script&gt;
        &lt;/script&gt;
