apply_rule &lt;- function(x, rule, swap = FALSE) {
  if (length(intersect(x, rule)) &lt; 2) {
    TRUE
  } else {
    before &lt;- match(rule[1], x)
    after &lt;- match(rule[2], x)
    correct &lt;- before &lt; after
    if (swap) {
      if (correct) {
        return(x)
      } else {
        x[c(after, before)] &lt;- rule
        return(x)
      }
    } else {
      return(correct)
    }
  }
}
